mapper.insert:
insert into phone_one_tap_attempts (
    request_id, provider, token_hash, request_ip, status, lease_id, lease_expires_time
) values (
    #{requestId}, #{provider}, #{tokenHash}, #{requestIp}, #{status},
    #{leaseId}, #{leaseExpiresTime}
)

mapper.select:
select 
from phone_one_tap_attempts
where id = #{id} and status = 'PROCESSING' and lease_id = #{leaseId}
  and lease_expires_time >= #{now}
for update

mapper.delete:
delete from phone_one_tap_attempts
where (
    status in ('SUCCEEDED', 'FAILED') and update_time < #{cutoff}
) or (
    status = 'PROCESSING' and lease_expires_time < #{cutoff}
)
order by id
limit #{limit}
